    23	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    24	                                         LocalDate checkIn, LocalDate checkOut, int guests, Reservation.RatePlan ratePlan) {
    25	        Room room = roomRepository.findByNumber(roomNumber)
    26	            .orElseThrow(() -> new IllegalArgumentException("Quarto não encontrado"));
    27	
    28	        if (guests < 1 || guests > room.getCapacity()) {
    29	            throw new IllegalArgumentException("Número de hóspedes inválido");
    30	        }
    31	
    32	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    33	            throw new IllegalArgumentException("Datas inválidas");
    34	        }
    35	
    36	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
    37	        if (!conflicts.isEmpty()) {
    38	            throw new IllegalArgumentException("Quarto não disponível");
    39	        }
    40	
    41	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    42	        BigDecimal nightlyRate = PricingCalculator.calculateNightlyRate(room.getNightlyRate(), checkIn);
    43	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(nightlyRate, nights);
    44	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
    45	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
    46	
    47	        Reservation reservation = new Reservation(roomNumber, guestName, guestEmail, guestCpf,
    48	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
    49	
    50	        return reservationRepository.save(reservation);
    51	    }
