    96	
    97	        if (reservation.getStatus() == Reservation.Status.CHECKED_IN ||
    98	            reservation.getStatus() == Reservation.Status.CHECKED_OUT ||
    99	            reservation.getStatus() == Reservation.Status.CANCELLED) {
