     3	public class EmailValidator {
     4	    public static boolean isValid(String email) {
     5	        if (email == null || email.isBlank()) {
     6	            return false;
     7	        }
     8	
     9	        int atCount = 0;
    10	        int atIndex = -1;
    11	        for (int i = 0; i < email.length(); i++) {
    12	            if (email.charAt(i) == '@') {
    13	                atCount++;
    14	                atIndex = i;
    15	            }
    16	        }
    17	
    18	        if (atCount != 1) {
    19	            return false;
    20	        }
    21	
    22	        if (atIndex == 0 || atIndex == email.length() - 1) {
    23	            return false;
    24	        }
    25	
    26	        String domain = email.substring(atIndex + 1);
    27	        int dotCount = 0;
    28	        for (char c : domain.toCharArray()) {
    29	            if (c == '.') {
    30	                dotCount++;
    31	            }
    32	        }
    33	
    34	        return dotCount >= 1 && !domain.startsWith(".") && !domain.endsWith(".");
    35	    }
    36	}
