     7	public class PricingCalculator {
     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = BigDecimal.valueOf(0.15);
    10	
    11	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    12	        if (isHighSeason(date)) {
    13	            return Money.round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
    14	        }
    15	        return baseRate;
    16	    }
    17	
    18	    public static BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights) {
    19	        return Money.round(nightlyRate.multiply(BigDecimal.valueOf(nights)));
    20	    }
    21	
    22	    public static BigDecimal calculateDiscount(BigDecimal subtotal, Reservation.RatePlan ratePlan) {
    23	        if (ratePlan == Reservation.RatePlan.NON_REFUNDABLE) {
    24	            return Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    25	        }
    26	        return BigDecimal.ZERO;
    27	    }
    28	
    29	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    30	        return Money.round(subtotal.subtract(discount));
    31	    }
    32	
    33	    private static boolean isHighSeason(LocalDate date) {
    34	        int month = date.getMonthValue();
    35	        int day = date.getDayOfMonth();
    36	
    37	        if (month == 7) {
    38	            return true;
    39	        }
    40	
    41	        if (month == 12) {
    42	            return true;
    43	        }
    44	
    45	        if (month >= 1 && month <= 2) {
    46	            return true;
    47	        }
    48	
    49	        return false;
    50	    }
    51	}

