 70	        MessageProcessingContext context = new MessageProcessingContext(new ArrayList<>());
 71	
 72	        EmailValidationRule rule = new EmailValidationRule();
 73	        rule.process(message, context);
 74	
 75	        assertEquals(Message.Status.BLOCKED, message.getStatus());
 76	    }
 77	
 78	    @Test
 79	    void shouldNotBlockValidEmail() {
 80	        Message message = new Message(Message.Channel.EMAIL, "user@example.com", "Subject", "Body");
 81	        MessageProcessingContext context = new MessageProcessingContext(new ArrayList<>());
 82	
 83	        EmailValidationRule rule = new EmailValidationRule();
 84	        rule.process(message, context);
 85	
 86	        assertEquals(Message.Status.SENT, message.getStatus());
 87	    }
 88	}
